Rで関数を実装

関数定義


# ユークリッドの互除法
gcd &lt;- function(a, b){
  if (!(a %% 1 == 0 & b %% 1 == 0 & a &gt; 0 & b &gt; 0)) {
    cat('入力が自然数じゃないのでやり直し')
  } 
  else if (a &lt; b) {
    w &lt;- a
    a &lt;- b
    b &lt;- w
  }
  while (b != 0) {
    r &lt;- a %% b
    a &lt;- b
    b &lt;- r
  }
  return(a)
}


