Pythonで実装

関数定義


# ユークリッドの互除法
def gcd(a, b):
  if not (a % 1 == 0 and b % 1 == 0 and a &gt; 0 and b &gt; 0):
    print('入力が自然数じゃないのでやり直し')
  elif a &lt; b:
    w = a
    a = b
    b = w
  while not b == 0:
    r = a % b
    a = b
    b = r
  else:
    return(a)


