R

再帰関数を呼び出す用のRecallという関数もある

gcd3 &lt;- function(a, b){
  if (!(a %% 1 == 0 & b %% 1 == 0 & a &gt; 0 & b &gt; 0)) {
    cat('入力が自然数じゃないのでやり直し')
  } 
  else {
    if (a &lt; b) {
      tmp &lt;- a; a &lt;- b; b &lt;- tmp
    }
    if (a %% b != 0) {
      return(Recall(b, a %% b)) # またはgcd(b, a %% b)
    }
    else return(b)
  }
}


